DataStream<ClickEvent> events = env
    .fromSource(kafkaSource, WatermarkStrategy
        .<ClickEvent>forBoundedOutOfOrderness(Duration.ofSeconds(30))
        .withTimestampAssigner((e, ts) -> e.getEventTimeMillis()),
        "clickstream-events");

events
    .keyBy(ClickEvent::getSessionId)
    .window(EventTimeSessionWindows.withGap(Time.minutes(30)))
    .aggregate(new SessionAggregator())
    .sinkTo(idempotentUpsertSink);  // keyed on sessionId -> overwrite on replay

// Enable exactly-once checkpointing to durable storage
env.enableCheckpointing(60_000, CheckpointingMode.EXACTLY_ONCE);
env.getCheckpointConfig().setCheckpointStorage("s3://flink-checkpoints/sessions/");

-- v1 table is currently served via the alias 'sessions_current'
-- v2 reprocessing job has written corrected results into sessions_v2 and caught up to live

BEGIN;
  -- Atomically swap the view/alias to the reprocessed table
  CREATE OR REPLACE VIEW sessions_current AS SELECT * FROM sessions_v2;
COMMIT;

-- Validate, then decommission the old version
DROP TABLE sessions_v1;
